import lib "example.test/project/lib"
type Item struct { Field int }
type Items []Item
type List[T any] []T
type Dict[K comparable, V any] map[K]V
type Count int
type Pointer *[2]Item
func Probe(foreign lib.Foreign, cross lib.Forward[Item], items Items, dict Dict[string, Item], ch <-chan Item, text string, n Count, grid [][]Item, iter func(func(int, Item) bool)) {
 for i, value := range items { _ = i; _ = value.Field }
 for key, value := range dict { _ = key; _ = value.Field }
 for value := range ch { _ = value.Field }
 for index, r := range text { _ = index; _ = r }
 for i := range n { _ = i }
 for i, value := range [2]Item{} { _ = i; _ = value.Field }
 for i, value := range (&[2]Item{}) { _ = i; _ = value.Field }
 for _, value := range (List[Item]{}) { _ = value.Field }
 for _, row := range grid { for _, cell := range row { _ = cell.Field } }
 for index, value := range iter { _ = index; _ = value.Field }
 for index, r := range "ab" { _ = index; _ = r }
 for index := range 3 { _ = index }
 for index := range 'a' { _ = index }
 var pointer Pointer
 for _, value := range pointer { _ = value.Field }
 for _, value := range foreign { _ = value.Remote }
 for _, value := range cross { _ = value.Field }
 var old Item
 for _, old = range items { _ = old.Field }
 _ = old.Field
 { items := []string{"a"}; for _, value := range items { _ = value } }
}
func Generic[Item any](items List[Item]) { for _, value := range items { _ = value } }

